Solution A: function simulateFlight(canvasId) {
    // -------------------------------------------------------------
    // Flight simulator with intentional realistic aviation bugs
    // -------------------------------------------------------------
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2;

    // -------------------------- State ----------------------------
    const state = {
        // Position (meters)
        x: 0,
        y: 1000, // altitude
        z: 0,
        // Velocity (m/s)
        speed: 150,
        // Orientation (radians)
        pitch: 0,
        roll: 0,
        yaw: 0,
        // Controls
        throttle: 0.7, // 0‑1
        // Fuel (kg)
        fuel: 5000,
        // Instruments (with bug-induced errors)
        instSpeed: 150,
        instAlt: 1000,
        instHeading: 0,
        // Timing helpers for bugs
        gForce: 1,
        altStickTimer: 0,
        compassBugTimer: 0,
        engineFluctTimer: 0,
    };

    // ------------------------ Constants -------------------------
    const MAX_SPEED = 300; // m/s
    const MIN_SPEED = 0;
    const FUEL_BURN_RATE = 0.02; // kg per (throttle * speed) per second
    const GRAVITY = 9.81; // m/s²
    const FRAME_MS = 1000 / 60;

    // --------------------------- Utils --------------------------
    function clamp(v, min, max) { return v < min ? min : v > max ? max : v; }
    function radToDeg(r) { return r * (180 / Math.PI); }
    function degToRad(d) { return d * (Math.PI / 180); }

    // --------------------------- Bugs ---------------------------
    // Instrument lag during high G‑forces
    function applyGForceLag(delta) {
        // Compute vertical acceleration ≈ G‑force
        const verticalAcc = -state.throttle * state.speed * Math.sin(state.pitch) / 30;
        const newG = 1 + verticalAcc / GRAVITY;
        const gDiff = Math.abs(newG - state.gForce);
        if (gDiff > 0.3) { // high G threshold
            // Lag instruments by smoothing toward real values
            const lagFactor = 0.9;
            state.instSpeed = state.instSpeed * lagFactor + state.speed * (1 - lagFactor);
            state.instAlt   = state.instAlt   * lagFactor + state.y      * (1 - lagFactor);
            // Visual indicator: flash speed/alt bars
            ctx.fillStyle = 'rgba(255,0,0,0.2)';
            ctx.fillRect(0, height - 40, width, 40);
        } else {
            state.instSpeed = state.speed;
            state.instAlt = state.y;
        }
        state.gForce = newG;
    }

    // Altimeter stickiness at specific altitude bands
    function applyAltimeterStickiness(delta) {
        const band = Math.floor(state.y / 1000);
        if (band !== state.lastBand) {
            state.altStickTimer = 1.5; // seconds of stickiness
            state.lastBand = band;
        }
        if (state.altStickTimer > 0) {
            state.altStickTimer -= delta;
            // keep displayed altitude unchanged
            // visual cue: small wobble around altitude box
            ctx.strokeStyle = 'yellow';
            ctx.strokeRect(10, 10, 120, 30);
        } else {
            state.instAlt = state.y;
        }
    }

    // Compass deviation near magnetic anomalies
    function applyCompassAnomaly(delta) {
        // Anomalies centered at 45°, 180°, 270°
        const headingDeg = (radToDeg(state.yaw) + 360) % 360;
        const anomalies = [45, 180, 270];
        const close = anomalies.some(a => Math.abs(headingDeg - a) < 10);
        if (close) {
            state.compassBugTimer = 2; // seconds the deviation lasts
        }
        if (state.compassBugTimer > 0) {
            state.compassBugTimer -= delta;
            const deviation = Math.sin(performance.now() / 200) * degToRad(5); // up to ±5°
            state.instHeading = (state.yaw + deviation) % (2 * Math.PI);
            // visual cue: compass box flashing
            ctx.strokeStyle = 'orange';
            ctx.strokeRect(width - 130, 10, 120, 30);
        } else {
            state.instHeading = state.yaw;
        }
    }

    // Engine power fluctuation during steep climbs
    function applyEngineFluctuation(delta) {
        if (radToDeg(state.pitch) > 30) {
            state.engineFluctTimer = 0.5; // half‑second fluctuation window
        }
        if (state.engineFluctTimer > 0) {
            state.engineFluctTimer -= delta;
            // Random bite in throttle effectiveness
            const fluct = 0.7 + Math.random() * 0.6; // 70‑130%
            state.effectiveThrottle = state.throttle * fluct;
            // visual cue: engine gauge red bar flicker
            ctx.fillStyle = 'rgba(255,0,0,0.3)';
            ctx.fillRect(width - 150, height - 30, 140, 20);
        } else {
            state.effectiveThrottle = state.throttle;
        }
    }

    // --------------------------- Physics -------------------------
    function updatePhysics(delta) {
        // Update speed based on throttle and engine fluctuation
        const targetAcc = (state.effectiveThrottle - 0.5) * 5; // +/- 2.5 m/s²
        state.speed = clamp(state.speed + targetAcc * delta, MIN_SPEED, MAX_SPEED);

        // Convert orientation to velocity vector
        const forward = Math.cos(state.pitch);
        const vertical = Math.sin(state.pitch);
        const dx = Math.cos(state.yaw) * forward * state.speed * delta;
        const dz = Math.sin(state.yaw) * forward * state.speed * delta;
        const dy = vertical * state.speed * delta - GRAVITY * delta; // gravity pulls down

        state.x += dx;
        state.z += dz;
        state.y = Math.max(state.y + dy, 0); // cannot go below ground

        // Fuel consumption
        state.fuel = Math.max(state.fuel - FUEL_BURN_RATE * state.throttle * state.speed * delta, 0);
    }

    // --------------------------- Input ---------------------------
    const keys = {};
    window.addEventListener('keydown', e => { keys[e.code] = true; });
    window.addEventListener('keyup', e => { keys[e.code] = false; });

    function handleInput(delta) {
        const turnRate = degToRad(45) * delta; // 45°/s
        const pitchRate = degToRad(30) * delta;

        if (keys['ArrowUp'])    state.throttle = clamp(state.throttle + 0.5 * delta, 0, 1);
        if (keys['ArrowDown'])  state.throttle = clamp(state.throttle - 0.5 * delta, 0, 1);
        if (keys['KeyW'])       state.pitch = clamp(state.pitch + pitchRate, -degToRad(90), degToRad(90));
        if (keys['KeyS'])       state.pitch = clamp(state.pitch - pitchRate, -degToRad(90), degToRad(90));
        if (keys['KeyA'])       state.roll  = clamp(state.roll  - turnRate, -degToRad(180), degToRad(180));
        if (keys['KeyD'])       state.roll  = clamp(state.roll  + turnRate, -degToRad(180), degToRad(180));
        if (keys['KeyQ'])       state.yaw   = (state.yaw - turnRate) % (2 * Math.PI);
        if (keys['KeyE'])       state.yaw   = (state.yaw + turnRate) % (2 * Math.PI);
    }

    // --------------------------- Render ---------------------------
    function clear() {
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, width, height);
    }

    function drawHorizon() {
        const horizonY = centerY + Math.tan(state.pitch) * 200;
        ctx.save();
        ctx.translate(centerX, horizonY);
        ctx.rotate(state.roll);
        ctx.fillStyle = '#555';
        ctx.fillRect(-width, -height, width * 2, height);
        ctx.restore();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, horizonY);
        ctx.lineTo(width, horizonY);
        ctx.stroke();
    }

    function drawTerrain() {
        ctx.strokeStyle = '#060';
        ctx.lineWidth = 1;
        for (let i = -5; i <= 5; i++) {
            const depth = i * 100;
            const scale = 200 / (200 + depth);
            const y = centerY + Math.tan(state.pitch) * depth * scale;
            ctx.beginPath();
            ctx.moveTo(0, y);
            ctx.lineTo(width, y);
            ctx.stroke();
        }
    }

    function drawHUD() {
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(0, height - 50, width, 50);
        ctx.fillStyle = '#0f0';
        ctx.font = '14px monospace';
        const speed = Math.round(state.instSpeed);
        const alt = Math.round(state.instAlt);
        const heading = Math.round(radToDeg(state.instHeading) % 360);
        const fuel = Math.round(state.fuel);
        ctx.fillText(`SPD:${speed}kt`, 10, height - 15);
        ctx.fillText(`ALT:${alt}m`, 110, height - 15);
        ctx.fillText(`HDG:${heading}°`, 210, height - 15);
        ctx.fillText(`FUEL:${fuel}kg`, 310, height - 15);
    }

    // --------------------------- Main Loop -----------------------
    let lastTime = performance.now();
    function loop(now) {
        const delta = (now - lastTime) / 1000; // seconds
        lastTime = now;
        // Clear frame
        clear();
        // Input & physics
        handleInput(delta);
        applyEngineFluctuation(delta);
        applyGForceLag(delta);
        applyAltimeterStickiness(delta);
        applyCompassAnomaly(delta);
        updatePhysics(delta);
        // Rendering
        drawTerrain();
        drawHorizon();
        drawHUD();
        // Loop
        requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
}

Solution B: ```javascript
/**
 * FlightSimulator - simple 2D flight simulator with intentional bugs.
 * @param {string} canvasId - ID of a 500x500 px canvas element.
 *
 * IMPORTANT: The bugs introduced below are intentional and documented within
 * the code. This implementation is meant for demonstration only.
 */
function FlightSimulator(canvasId) {
    // ==========================================================
    //   INITIAL SETUP: GLIDEOVER RENDER LOOP AND STATE
    // ==========================================================
    const canvas = document.getElementById(canvasId);
    if (!canvas || canvas.width !== 500 || canvas.height !== 500) {
        console.error('Canvas must exist and be 500x500 px.');
        return;
    }
    const ctx = canvas.getContext('2d');

    // Physics and state
    let state = {
        // Position & velocity (in arbitrary units; 1 px ~ 30 ft)
        alt: 5000,          // current altitude (ft)
        speed: 250,         // ground speed (knots)
        throttle: 50,       // % throttle
        enginePower: 1.0,   // engine power factor (0..1)
        pitch: 0,           // degrees relative to horizon
        roll: 0,            // roll angle (bank) degrees
        yaw: 0,             // heading degrees
        // Simulated orientation velocities
        pitchRate: 0,       // degrees per second
        rollRate: 0,        // degrees per second
        yawRate: 0,         // degrees per second
        // Fuel
        fuel: 1000          // liters
    };

    // Instrument readings (may lag or be sticky)
    let instruments = {
        speed: state.speed,
        alt: state.alt,
        heading: state.yaw,
        throttle: state.throttle,
        enginePower: state.enginePower
    };

    // BUG FLAGS
    let bugs = {
        instrumentLag: false,
        altStuck: false,
        compassDrift: false,
        engineFluct: false
    };

    // Timers for lag and stickiness
    let lagTimer = 0;
    let altStickTimer = 0;
    let compassTimer = 0;
    let engineTimer = 0;

    // Constants
    const FPS = 60;
    const dt = 1 / FPS;
    const THROTTLE_STEP = 2;          // % per key press
    const PITCH_STEP = 0.5;           // degrees per key press
    const YAW_STEP = 1;               // degrees per key press
    const ROLL_STEP = 1;              // degrees per key press
    const MAX_SPEED = 400;
    const MAX_ALT = 40000;
    const MIN_ALT = 0;
    const GAS = 0.001;                // g per unit speed for education purposes
    const MAG_ANECHO = [30, 90, 210, 330]; // headings with anomaly influence

    // ==========================================================
    //   INPUT HANDLING
    // ==========================================================
    const keys = {};
    document.addEventListener('keydown', e => { keys[e.key.toLowerCase()] = true; });
    document.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

    // ==========================================================
    //   MAIN UPDATE LOOP
    // ==========================================================
    function update() {
        // 1. Process input
        // Throttle
        if (keys['w']) {
            state.throttle = Math.min(100, state.throttle + THROTTLE_STEP);
        }
        if (keys['s']) {
            state.throttle = Math.max(0, state.throttle - THROTTLE_STEP);
        }

        // Pitch
        if (keys['arrowup']) state.pitchRate = Math.min(5, state.pitchRate + PITCH_STEP);
        if (keys['arrowdown']) state.pitchRate = Math.max(-5, state.pitchRate - PITCH_STEP);
        // Yaw
        if (keys['arrowleft']) state.yawRate = Math.max(-5, state.yawRate - YAW_STEP);
        if (keys['arrowright']) state.yawRate = Math.min(5, state.yawRate + YAW_STEP);
        // Roll
        if (keys['a']) state.roll = Math.max(-5, state.rollRate - ROLL_STEP);
        if (keys['d']) state.rollRate = Math.min(5, state.rollRate + ROLL_STEP);

        // 2. Update physics
        // Simplified: speed depends on throttle and engine power
        const throttleFactor = state.throttle / 100;
        const desiredSpeed = throttleFactor * MAX_SPEED;
        const speedChange = (desiredSpeed - state.speed) * 0.05;
        state.speed += speedChange * dt * 60; // smoothing

        // Altitude change from pitch
        const altitudeChange = Math.sin(state.pitch * Math.PI / 180) * state.speed * dt * 30; // arbitrary
        state.alt += altitudeChange;
        state.alt = Math.max(MIN_ALT, Math.min(MAX_ALT, state.alt));

        // Update orientation
        state.pitch += state.pitchRate * dt * 60;
        state.roll += state.rollRate * dt * 60;
        state.yaw = (state.yaw + state.yawRate * dt * 60) % 360;

        // 3. Fuel consumption
        state.fuel -= state.speed * 0.01 * dt * 60; // arbitrary consumption
        state.fuel = Math.max(0, state.fuel);

        // 4. Engine power in response to steep climb (bug)
        if (Math.abs(state.pitch) > 30 && state.throttle > 70) {
            bugs.engineFluct = true;
            state.enginePower = 1.0 + 0.1 * Math.sin(performance.now() * 0.01);
        } else {
            bugs.engineFluct = false;
            state.enginePower = 1.0;
        }

        // 5. G-force simulation
        const netG = Math.abs(state.speedChange || 0) * GAS;
        if (netG > 4) { // above 4g threshold
            bugs.instrumentLag = true;
            lagTimer += dt;
        } else {
            bugs.instrumentLag = false;
            lagTimer = 0;
        }

        // 6. Altimeter stickiness bug at 2000-2100 ft
        if (state.alt > 1900 && state.alt < 2100) {
            bugs.altStuck = true;
            altStickTimer += dt;
        } else {
            bugs.altStuck = false;
            altStickTimer = 0;
        }

        // 7. Compass deviation near magnetic anomalies
        const headingMod = state.yaw % 360;
        if (MAG_ANECHO.some(h => Math.abs(headingMod - h) < 5)) {
            bugs.compassDrift = true;
            compassTimer += dt;
        } else {
            bugs.compassDrift = false;
            compassTimer = 0;
        }

        // 8. Update instrument readings with bugs
        // Slow ship instrument lag
        if (bugs.instrumentLag) {
            instruments.speed = lerp(instruments.speed, state.speed, 0.02);
            instruments.alt = lerp(instruments.alt, state.alt, 0.02);
        } else {
            instruments.speed = state.speed;
            instruments.alt = state.alt;
        }

        // Altimeter stickiness: use old reading until timer passes
        if (bugs.altStuck) {
            // keep old reading
        } else {
            // gradually recover
            instruments.alt = lerp(instruments.alt, state.alt, 0.1);
        }

        // Compass deviation
        if (bugs.compassDrift) {
            instruments.heading = (state.yaw + Math.sin(compassTimer * 3) * 10) % 360;
        } else {
            instruments.heading = state.yaw;
        }

        // Fuel & Throttle are direct
        instruments.fuel = state.fuel;
        instruments.throttle = state.throttle;
        instruments.enginePower = state.enginePower;

        // 9. Render
        render();

        // 10. Loop
        requestAnimationFrame(update);
    }

    // ==========================================================
    //   RENDERING
    // ==========================================================
    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw background
        ctx.fillStyle = '#003399'; // sky
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Horizon
        const horizonY = 250 - (state.alt / 2000) * 50 + Math.sin(state.roll * Math.PI / 180) * 10;
        ctx.save();
        ctx.translate(250, horizonY);
        ctx.rotate(state.roll * Math.PI / 180);
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(-250, 0);
        ctx.lineTo(250, 0);
        ctx.stroke();
        ctx.restore();

        // Simple terrain line below horizon
        ctx.strokeStyle = '#555555';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, horizonY);
        ctx.lineTo(500, horizonY);
        ctx.stroke();

        // Aircraft symbol
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(250 - 10, 250);
        ctx.lineTo(250 + 10, 250);
        ctx.moveTo(250, 250 - 10);
        ctx.lineTo(250, 250 + 10);
        ctx.stroke();

        // HUD
        ctx.fillStyle = 'rgba(0,0,0,0.3)';
        ctx.fillRect(0, 400, 500, 100);
        ctx.fillStyle = '#FFFFFF';
        ctx.font = '14px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`Speed: ${Math.round(instruments.speed)} kt`, 10, 420);
        ctx.fillText(`Altitude: ${Math.round(instruments.alt)} ft`, 10, 440);
        ctx.fillText(`Heading: ${Math.round(instruments.heading)}°`, 10, 460);
        ctx.fillText(`Throttle: ${Math.round(instruments.throttle)}%`, 10, 480);
        ctx.fillText(`Fuel: ${Math.round(instruments.fuel)} L`, 10, 500);

        // Visual bug indicators
        // Instrument lag
        if (bugs.instrumentLag) {
            ctx.fillStyle = 'rgba(255,0,0,0.5)';
            ctx.fillRect(450, 410, 40, 20);
            ctx.fillStyle = '#FFFFFF';
            ctx.fillText('Lag', 470, 425);
        }
        // Altimeter stuck
        if (bugs.altStuck) {
            ctx.fillStyle = 'rgba(255,255,0,0.5)';
            ctx.fillRect(450, 440, 40, 20);
            ctx.fillStyle = '#000000';
            ctx.fillText('Stuck', 470, 455);
        }
        // Compass drift
        if (bugs.compassDrift) {
            ctx.fillStyle = 'rgba(0,0,255,0.5)';
            ctx.fillRect(450, 470, 40, 20);
            ctx.fillStyle = '#FFFFFF';
            ctx.fillText('Drift', 470, 485);
        }
        // Engine fluctuation
        if (bugs.engineFluct) {
            ctx.fillStyle = 'rgba(255,0,255,0.5)';
            ctx.fillRect(450, 500, 40, 20);
            ctx.fillStyle = '#FFFFFF';
            ctx.fillText('Fluct', 470, 515);
        }
    }

    // ==========================================================
    //   HELPERS
    // ==========================================================
    function lerp(a, b, t) {
        return a + (b - a) * t;
    }

    // ==========================================================
    //   START
    // ==========================================================
    requestAnimationFrame(update);
}
